          } else if (rank == 0) {
            asm volatile("mbarrier.arrive.shared::cta.b64 _, [%0];" ::"r"(fl) : "memory");
          }
        }
        if (UNI) __syncwarp();
      }
    }
  } else if (warp == 1 && rank == 0) {
    if (UNI || lane == 0) {
      const uint32_t idesc1 = (1u << 4) | (2u << 7) | (2u << 10) | ((uint32_t)(c.n1 >> 3) << 17) | ((uint32_t)(CG * 128 >> 4) << 24);
      const uint32_t idesc2 = (1u << 4) | (2u << 7) | (2u << 10) | ((uint32_t)(c.n2 >> 3) << 17) | ((uint32_t)(CG * 128 >> 4) << 24);
      const uint64_t t0 = clock64(), g0 = gtime();
      for (int i = 0; i < c.nk; ++i) {
        const int s = c.rot ? i % c.S : 0;
        if (c.ring == 2) mbar_wait(smem_u32(&full[s]), (i / c.S) & 1);
        else if (c.ring == 1 && i >= c.S && (s % c.we) == 0) mbar_wait(smem_u32(&empty[s]), ((i / c.S) - 1) & 1);
        asm volatile("tcgen05.fence::after_thread_sync;");
        const uint32_t a = sbase + s * stageBytes, b = a + 16384;
        const uint64_t da = sw128_desc(a), db = sw128_desc(b), db2 = sw128_desc(b + eb1 * 128);
