          }
          commit<CG>(smem_u32(&empty[s]));
        }
        if (UNI) __syncwarp();
      }
      if (!UNI || elect_one()) commit<CG>(smem_u32(&accum));
      if (UNI) __syncwarp();
      mbar_wait(smem_u32(&accum), 0);
      const uint64_t t1 = clock64(), g1 = gtime();
      if (lane == 0) { out[blockIdx.x * 3] = t1 - t0; out[blockIdx.x * 3 + 1] = g1 - g0; out[blockIdx.x * 3 + 2] = 1; }
    }
  }
  __syncwarp();
  mbar_wait(smem_u32(&accum), 0);
  asm volatile("tcgen05.fence::before_thread_sync;");
  csync<CG>();
  if (warp == 3) {
    asm volatile("tcgen05.fence::after_thread_sync;");
    if constexpr (CG == 2) asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(tcols));
    else asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(tcols));
  }
}
template <int CG, int UNI>
int go(CUtensorMap& a, CUtensorMap& b, CUtensorMap& d, Cfg c, unsigned long long* out, int grid, size_t smem, cudaStream_t st) {
  auto k = ringk<CG, UNI>;
  cudaFuncSetAttribute(k, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3(grid); cfg.blockDim = dim3(128); cfg.dynamicSmemBytes = smem; cfg.stream = st;
  cudaLaunchAttribute at[1];
  at[0].id = cudaLaunchAttributeClusterDimension; at[0].val.clusterDim.x = CG; at[0].val.clusterDim.y = 1; at[0].val.clusterDim.z = 1;
  cfg.attrs = at; cfg.numAttrs = CG == 2 ? 1 : 0;
  cudaLaunchKernelEx(&cfg, k, a, b, d, c, out);
  return (int)cudaGetLastError();
}
extern "C" int launch(int cg, int uni, const void* W, int wrows, const void* E, int erows, Cfg c, unsigned long long* out, int grid, cudaStream_t st) {
  CUtensorMap mW, mE1, mE2;
  int eb1 = c.n1 / cg, eb2 = c.n2 / cg; if (eb2 < 8) eb2 = 8;
  auto enc = [&](CUtensorMap* m, const void* p, int rows, int boxr) -> int {
    cuuint64_t d[2] = {3072, (cuuint64_t)rows}, s[1] = {3072 * 4};
    cuuint32_t b[2] = {32, (cuuint32_t)boxr}, e[2] = {1, 1};
    return (int)cuTensorMapEncodeTiled(m, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 2, (void*)p, d, s, b, e, CU_TENSOR_MAP_INTERLEAVE_NONE,
      CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
  };
  if (enc(&mW, W, wrows, 128)) return 1001;
  if (enc(&mE1, E, erows, eb1)) return 1002;
  if (enc(&mE2, E, erows, eb2)) return 1003;
  size_t stageBytes = 16384 + (c.n1 / cg + c.n2 / cg) * 128;
  size_t smem = c.S * stageBytes + 1024;
  if (cg == 2 && uni) return go<2, 1>(mW, mE1, mE2, c, out, grid, smem, st);
  if (cg == 2) return go<2, 0>(mW, mE1, mE2, c, out, grid, smem, st);
  if (uni) return go<1, 1>(mW, mE1, mE2, c, out, grid, smem, st);
  return go<1, 0>(mW, mE1, mE2, c, out, grid, smem, st);
}
