#include <cuda_runtime.h>
#include <cuda.h>
#include <cstdint>

// B > 256 (dispatched from kernel.cu; correct for any 1 <= B <= 1024): warp-specialised 2SM tcgen05 TF32 GEMM.
// A cluster of two CTAs computes a 256-row W tile (cta_group::2 UMMA, M = 256) against one batch tile of
// ntile = Bpad (B <= 512) or two batch tiles of ntile = roundup(B / 2, 16) (B > 512, sibling pairs share the W tile
// through L2). ntile <= 256 uses one accumulator and 2-k-block stages; ntile > 256 uses two accumulators (N1 = 256 at
// TMEM column 0, N2 = ntile - 256 at column 256) and 1-k-block stages, so TMEM column t always holds batch row boff + t.
// Each CTA holds its own 128 W rows and half of each accumulator's emb rows; only the leader issues the MMAs.
// Roles are warp-uniform as in CUTLASS's PipelineTmaUmmaAsync: warp 0 of each CTA is the TMA producer (waits its
// empty barrier, issues TMA to the leader's full barrier), warp 1 of the leader is the MMA issuer (waits full,
// issues UMMAs, multicasts the commit to both CTAs' empty barriers). Both loops run on the whole warp and only the
// issue is elected: with a single-lane role branch (warp == 1 && lane == 0) nvcc wraps every UTCHMMA in an
// ELECT/BRA.U.ANY uniformity loop, which set the ~950-1100 clk per-stage floor of the r3/r4 rings (E2, r5).
// W loads carry L2 evict_first. Epilogue: all 8 warps, TMEM lane quadrant warp % 4, column half warp / 4.
namespace {
constexpr int kD = 3072, kN = 6 * kD, kRows = 128, kBK = 32, kKB = kD / kBK, kWBlk = kRows * kBK * 4;
constexpr int kMaxStages = 16, kSmemDyn = 225 * 1024, kThreads = 256;
struct OutPtrs { float* p[6]; };
struct TileCfg { int B, ntile, n1, n2, kbs, stages, nb, tmem_cols; };

#if defined(__CUDA_ARCH_FEAT_SM100_ALL)
__device__ __forceinline__ uint32_t smem_u32(const void* p) { return (uint32_t)__cvta_generic_to_shared(p); }
__device__ __forceinline__ uint32_t mapa0(uint32_t a) {
  uint32_t r;
  asm volatile("mapa.shared::cluster.u32 %0, %1, %2;" : "=r"(r) : "r"(a), "r"(0));
  return r;
}
__device__ __forceinline__ bool try_wait(uint32_t bar, uint32_t par) {
  uint32_t ok;
  asm volatile("{ .reg .pred p; mbarrier.try_wait.parity.shared::cta.b64 p, [%1], %2; selp.u32 %0, 1, 0, p; }"
               : "=r"(ok) : "r"(bar), "r"(par) : "memory");
  return ok != 0;
}
__device__ __forceinline__ void mbar_wait(uint32_t bar, uint32_t par) {
  uint32_t n = 0;
  while (!try_wait(bar, par))
    if (++n > (1u << 27)) __trap();   // a broken pipeline fails the call instead of hanging it
}
__device__ __forceinline__ void mbar_init(uint32_t bar) { asm volatile("mbarrier.init.shared::cta.b64 [%0], 1;" ::"r"(bar)); }
__device__ __forceinline__ uint32_t elect_one() {
  uint32_t pred = 0;
  asm volatile("{\n .reg .b32 rx;\n .reg .pred px;\n elect.sync rx|px, %1;\n selp.b32 %0, 1, 0, px;\n}"
               : "=r"(pred) : "r"(0xffffffffu));
  return pred;
}
__device__ __forceinline__ void umma_commit2(uint32_t bar) {
  asm volatile("tcgen05.commit.cta_group::2.mbarrier::arrive::one.shared::cluster.multicast::cluster.b64 [%0], %1;"
               ::"r"(bar), "h"((uint16_t)3) : "memory");
}
__device__ __forceinline__ void umma2(uint32_t t, uint64_t a, uint64_t b, uint32_t idesc, uint32_t acc) {
  asm volatile("{ .reg .pred p; setp.ne.b32 p, %4, 0; tcgen05.mma.cta_group::2.kind::tf32 [%0], %1, %2, %3, p; }"
               ::"r"(t), "l"(a), "l"(b), "r"(idesc), "r"(acc));
}
__device__ __forceinline__ void tma_w(uint32_t dst, const CUtensorMap* m, uint32_t bar, int x, int y, uint64_t pol) {
  asm volatile("cp.async.bulk.tensor.2d.cta_group::2.shared::cluster.global.mbarrier::complete_tx::bytes.L2::cache_hint [%0], [%1, {%3, %4}], [%2], %5;"
               ::"r"(dst), "l"((uint64_t)m), "r"(bar), "r"(x), "r"(y), "l"(pol) : "memory");
}
__device__ __forceinline__ void tma_e(uint32_t dst, const CUtensorMap* m, uint32_t bar, int x, int y) {
  asm volatile("cp.async.bulk.tensor.2d.cta_group::2.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1, {%3, %4}], [%2];"
               ::"r"(dst), "l"((uint64_t)m), "r"(bar), "r"(x), "r"(y) : "memory");
}
__device__ __forceinline__ uint64_t sw128_desc(uint32_t addr) {
  return (uint64_t)((addr & 0x3FFFF) >> 4) | ((uint64_t)1 << 16) | ((uint64_t)(1024 >> 4) << 32) | ((uint64_t)1 << 46) |
         ((uint64_t)2 << 61);
}
__device__ __forceinline__ void cluster_sync() {
  asm volatile("barrier.cluster.arrive.release.aligned;\nbarrier.cluster.wait.acquire.aligned;" ::: "memory");
}
#endif

__global__ void __launch_bounds__(kThreads, 1) tc_ws_kernel(const __grid_constant__ CUtensorMap mapW,
                                                           const __grid_constant__ CUtensorMap mapE1,
                                                           const __grid_constant__ CUtensorMap mapE2,
                                                           const float* __restrict__ bias, OutPtrs outs, TileCfg p) {
#if defined(__CUDA_ARCH_FEAT_SM100_ALL)
  extern __shared__ uint8_t smem_raw[];
  __shared__ __align__(8) uint64_t full[kMaxStages], empty[kMaxStages], accum;
  __shared__ uint32_t tmem_slot;
  const uint32_t sbase = (smem_u32(smem_raw) + 1023) & ~1023u;
  const int eb1 = p.n1 / 2, eb2 = p.n2 / 2;                      // emb rows per CTA for each accumulator
  const uint32_t e1Off = p.kbs * kWBlk, e2Off = e1Off + p.kbs * eb1 * 128;
  const uint32_t stageBytes = p.kbs * (kWBlk + (eb1 + eb2) * 128);   // per CTA
  const int nIt = kKB / p.kbs;
  const int warp = __shfl_sync(0xffffffffu, threadIdx.x >> 5, 0), lane = threadIdx.x & 31;
  uint32_t rank;
  asm volatile("mov.u32 %0, %%cluster_ctarank;" : "=r"(rank));
  const int pair = blockIdx.x >> 1;
  const int m0 = ((pair / p.nb) * 2 + (int)rank) * kRows;   // sibling batch tiles of one W tile are adjacent pairs
  const int boff = (pair % p.nb) * p.ntile;
  if (threadIdx.x == 0) {
    for (int i = 0; i < p.stages; ++i) { mbar_init(smem_u32(&full[i])); mbar_init(smem_u32(&empty[i])); }
    mbar_init(smem_u32(&accum));
    asm volatile("fence.mbarrier_init.release.cluster;");
    asm volatile("prefetch.tensormap [%0];" ::"l"((uint64_t)&mapW) : "memory");
    asm volatile("prefetch.tensormap [%0];" ::"l"((uint64_t)&mapE1) : "memory");
    asm volatile("prefetch.tensormap [%0];" ::"l"((uint64_t)&mapE2) : "memory");
  }
  if (warp == 3) {
    asm volatile("tcgen05.alloc.cta_group::2.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(smem_u32(&tmem_slot)), "r"(p.tmem_cols));
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::2.sync.aligned;");
  }
  asm volatile("tcgen05.fence::before_thread_sync;");
  cluster_sync();
  asm volatile("tcgen05.fence::after_thread_sync;");
  const uint32_t tmem = tmem_slot;

  if (warp == 0) {   // TMA producer (both CTAs, whole warp waits, one lane issues)
    uint64_t pol;
    asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
    for (int i = 0; i < nIt; ++i) {
      const int s = i % p.stages;
      if (i >= p.stages) mbar_wait(smem_u32(&empty[s]), ((i / p.stages) - 1) & 1);
      if (elect_one()) {
