        const uint32_t fb = mapa0(fl);   // the leader's full barrier collects the bytes of both CTAs
        if (rank == 0)
          asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;" ::"r"(fl), "r"(2 * stageBytes) : "memory");
        const uint32_t a = sbase + s * stageBytes;
        for (int j = 0; j < p.kbs; ++j) {
          const int kx = (i * p.kbs + j) * kBK;
          tma_w(a + j * kWBlk, &mapW, fb, kx, m0, pol);
          tma_e(a + e1Off + j * eb1 * 128, &mapE1, fb, kx, boff + (int)rank * eb1);
          if (p.n2) tma_e(a + e2Off + j * eb2 * 128, &mapE2, fb, kx, boff + p.n1 + (int)rank * eb2);
        }
      }
      __syncwarp();
    }
  } else if (warp == 1 && rank == 0) {   // MMA issuer (leader, whole warp waits, one lane issues)
    const uint32_t idesc1 = (1u << 4) | (2u << 7) | (2u << 10) | ((uint32_t)(p.n1 >> 3) << 17) | ((uint32_t)(2 * kRows >> 4) << 24);
    const uint32_t idesc2 = (1u << 4) | (2u << 7) | (2u << 10) | ((uint32_t)(p.n2 >> 3) << 17) | ((uint32_t)(2 * kRows >> 4) << 24);
    for (int i = 0; i < nIt; ++i) {
      const int s = i % p.stages;
      mbar_wait(smem_u32(&full[s]), (i / p.stages) & 1);
      asm volatile("tcgen05.fence::after_thread_sync;");
      const uint32_t a = sbase + s * stageBytes;
      const uint64_t da0 = sw128_desc(a), db0 = sw128_desc(a + e1Off), dc0 = sw128_desc(a + e2Off);
      const uint64_t da1 = sw128_desc(a + kWBlk), db1 = sw128_desc(a + e1Off + eb1 * 128), dc1 = sw128_desc(a + e2Off + eb2 * 128);
      if (elect_one()) {
#pragma unroll
        for (int k = 0; k < kBK / 8; ++k) {
          const uint32_t acc = (i | k) != 0;
          umma2(tmem, da0 + 2 * k, db0 + 2 * k, idesc1, acc);
          if (p.n2) umma2(tmem + 256, da0 + 2 * k, dc0 + 2 * k, idesc2, acc);
        }
        if (p.kbs == 2) {
#pragma unroll
          for (int k = 0; k < kBK / 8; ++k) {
            umma2(tmem, da1 + 2 * k, db1 + 2 * k, idesc1, 1u);
            if (p.n2) umma2(tmem + 256, da1 + 2 * k, dc1 + 2 * k, idesc2, 1u);
