  cluster_sync();
  if (warp == 3) {
    asm volatile("tcgen05.fence::after_thread_sync;");
    asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(p.tmem_cols));
  }
#endif
}
}  // namespace

extern "C" int adamod_tc_ws(const float* emb, const float* W, const float* bias, float* const* outs, int B,
                            cudaStream_t stream) {
  if (B < 1 || B > 1024) return 420;
  TileCfg p;
  p.B = B;
  p.nb = B <= 512 ? 1 : 2;
  p.ntile = ((B + p.nb - 1) / p.nb + 15) / 16 * 16;
  p.n1 = p.ntile < 256 ? p.ntile : 256;
  p.n2 = p.ntile - p.n1;
  p.kbs = p.n2 == 0 ? 2 : 1;
  p.tmem_cols = p.n2 ? 512 : p.n1 <= 32 ? 32 : p.n1 <= 64 ? 64 : p.n1 <= 128 ? 128 : 256;
  const int perK = kWBlk + p.ntile / 2 * 128, avail = kSmemDyn - 1024;
  p.stages = avail / (p.kbs * perK);
  if (p.stages > kMaxStages) p.stages = kMaxStages;
  CUtensorMap mW, mE1, mE2;
  cuuint32_t es[2] = {1, 1};
  cuuint64_t dW[2] = {(cuuint64_t)kD, (cuuint64_t)kN}, sW[1] = {(cuuint64_t)kD * 4};
  cuuint32_t bW[2] = {kBK, kRows};
  if (cuTensorMapEncodeTiled(&mW, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 2, (void*)W, dW, sW, bW, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
                             CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B,
                             CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS)
    return 421;
  // emb rows >= B are out of bounds and zero-filled by TMA.
  cuuint64_t dE[2] = {(cuuint64_t)kD, (cuuint64_t)B}, sE[1] = {(cuuint64_t)kD * 4};
  cuuint32_t bE1[2] = {kBK, (cuuint32_t)(p.n1 / 2)}, bE2[2] = {kBK, (cuuint32_t)(p.n2 ? p.n2 / 2 : 8)};
  if (cuTensorMapEncodeTiled(&mE1, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 2, (void*)emb, dE, sE, bE1, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
                             CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B,
                             CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS)
    return 422;
  if (cuTensorMapEncodeTiled(&mE2, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 2, (void*)emb, dE, sE, bE2, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
                             CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B,
                             CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS)
    return 423;
  static bool attr_set = false;
  if (!attr_set) {
    cudaFuncSetAttribute(tc_ws_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemDyn);
    attr_set = true;
  }
  OutPtrs op;
  for (int i = 0; i < 6; ++i) op.p[i] = outs[i];
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3(2 * (kN / (2 * kRows)) * p.nb);
  cfg.blockDim = dim3(kThreads);
  cfg.dynamicSmemBytes = p.stages * p.kbs * perK + 1024;
  cfg.stream = stream;
  cudaLaunchAttribute at[1];
  at[0].id = cudaLaunchAttributeClusterDimension;
  at[0].val.clusterDim.x = 2;
  at[0].val.clusterDim.y = 1;
  at[0].val.clusterDim.z = 1;
